<div class="certificate-workspace"><main><article class="certificate-sheet"><header><div><span class="certificate-company"><?= e($certificate['brand_name']?:$user['company_name']) ?></span><h2><?= e($certificate['template_name']) ?></h2><p><?= e($certificate['inspection_test_type']) ?></p></div><div class="certificate-number"><span>Certificate number</span><strong><?= e($certificate['certificate_number']) ?></strong><?= qhse_status_badge($certificate['display_status']) ?></div></header><section class="certificate-meta"><div><span>Customer</span><strong><?= e($certificate['customer_name']) ?></strong><small><?= e($certificate['customer_site']?:$certificate['customer_address']) ?></small></div><div><span>Project / Job</span><strong><?= e($certificate['project_job']?:'Not specified') ?></strong><small><?= e($certificate['location']) ?></small></div><div><span>Valid from</span><strong><?= e($certificate['valid_from']?:'Set on issue') ?></strong></div><div><span>Expiry</span><strong><?= e($certificate['expiry_date']?:'No expiry set') ?></strong></div></section><section><h3>Equipment</h3><div class="table-wrap"><table><thead><tr><th>AID</th><th>Description</th><th>Type</th><th>Manufacturer / Model</th><th>Serial number</th></tr></thead><tbody><?php foreach($certificate['equipment'] as $asset):?><tr><td><?= e($asset['asset_code']) ?></td><td><?= e($asset['name']) ?></td><td><?= e($asset['type_name']) ?></td><td><?= e(trim(($asset['brand_name']??'').' '.($asset['model_name']??''))) ?></td><td><?= e($asset['serial_no']?:'—') ?></td></tr><?php endforeach;?></tbody></table></div></section><section><h3>Technical result</h3><dl class="technical-results"><?php foreach($tech as $key=>$value):?><div><dt><?= e(ucwords(str_replace('_',' ',$key))) ?></dt><dd><?= e($value?:'—') ?></dd></div><?php endforeach;?></dl><div class="result-banner result-<?= strtolower($certificate['result']) ?>"><span>Result</span><strong><?= e($certificate['result']) ?></strong></div></section><section class="certificate-notes"><div><h3>Observations</h3><p><?= nl2br(e($certificate['observations']?:'No observations recorded.')) ?></p></div><div><h3>Remarks</h3><p><?= nl2br(e($certificate['remarks']?:'No remarks recorded.')) ?></p></div></section><footer><div><span>Technician</span><strong><?= e($certificate['technician_name']?:'Not assigned') ?></strong></div><div><span>Inspector</span><strong><?= e($certificate['inspector_name']?:'Not assigned') ?></strong></div><div><span>Approver</span><strong><?= e($certificate['approver_name']?:'Pending approval') ?></strong></div><div class="verify-block"><span>VERIFY</span><strong><?= e(substr($certificate['verification_token'],0,8)) ?></strong></div></footer></article></main><aside><section class="panel workflow-panel"><span class="eyebrow">Workflow</span><h2><?= e(ucwords(strtolower(str_replace('_',' ',$certificate['display_status'])))) ?></h2><div class="workflow-actions"><?php if($certificate['status']==='DRAFT'):?><form action="qhse-certificate-action" method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($id) ?>"><button class="primary" name="action" value="submit">Submit for review</button></form><?php elseif($certificate['status']==='AWAITING_REVIEW'&&qhse_can_approve($user)):?><form action="qhse-certificate-action" method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($id) ?>"><button class="primary" name="action" value="approve">Approve</button><textarea name="notes" placeholder="Reason required to reject"></textarea><button class="secondary danger-text" name="action" value="reject">Reject</button></form><?php elseif($certificate['status']==='APPROVED'&&qhse_can_approve($user)):?><form action="qhse-certificate-action" method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($id) ?>"><button class="primary" name="action" value="issue">Issue certificate</button></form><?php elseif($certificate['status']==='ISSUED'&&qhse_can_approve($user)):?><form action="qhse-certificate-action" method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($id) ?>"><textarea name="notes" required placeholder="Revocation reason"></textarea><button class="secondary danger-text" name="action" value="revoke">Revoke certificate</button></form><?php endif;?></div><a class="secondary full-button" href="qhse-certificate-print?id=<?= e($id) ?>" target="_blank">Print / Save as PDF</a><?php if($certificate['status']==='ISSUED'):?><a class="secondary full-button" href="qhse-certificate-verify?token=<?= e($certificate['verification_token']) ?>" target="_blank">Open verification page</a><?php endif;?></section><section class="panel timeline"><h2>Activity</h2><?php foreach($certificate['events'] as $event):?><article><strong><?= e(ucwords(strtolower(str_replace('_',' ',$event['event_type'])))) ?></strong><span><?= e($event['actor_name'].' · '.$event['occurred_at']) ?></span><?php if($event['notes']):?><p><?= e($event['notes']) ?></p><?php endif;?></article><?php endforeach;?></section></aside></div>
<?php else:$where=['c.owner_id=?'];$params=[$user['owner_id']];foreach(['status','certificate_type','customer_id'] as $filter)if(!empty($_GET[$filter])){$where[]='c.'.$filter.'=?';$params[]=$_GET[$filter];}$query=trim((string)($_GET['q']??''));if($query!==''){$where[]='(c.certificate_number LIKE ? OR cu.name LIKE ? OR e.name LIKE ?)';array_push($params,"%$query%","%$query%","%$query%");}$records=rows('SELECT c.*,cu.name customer_name,GROUP_CONCAT(DISTINCT e.name ORDER BY e.name SEPARATOR ", ") equipment_names FROM qhse_certificates c JOIN commercial_customers cu ON cu.id=c.customer_id LEFT JOIN qhse_certificate_equipment ce ON ce.certificate_id=c.id LEFT JOIN equipment e ON e.id=ce.equipment_id WHERE '.implode(' AND ',$where).' GROUP BY c.id ORDER BY c.created_at DESC',$params);?>
<section class="panel certificate-register"><form class="register-filters" method="get"><label>Search<input name="q" value="<?= e($query) ?>" placeholder="Certificate #, customer or equipment"></label><label>Status<select name="status"><option value="">All statuses</option><?php foreach(['DRAFT','AWAITING_REVIEW','APPROVED','ISSUED','REJECTED','REVOKED','SUPERSEDED'] as $status):?><option <?= ($_GET['status']??'')===$status?'selected':'' ?>><?= $status ?></option><?php endforeach;?></select></label><label>Type<select name="certificate_type"><option value="">All types</option><?php foreach(array_unique(array_column($templates,'certificate_type')) as $type):?><option value="<?= e($type) ?>" <?= ($_GET['certificate_type']??'')===$type?'selected':'' ?>><?= e(qhse_certificate_type_label($type)) ?></option><?php endforeach;?></select></label><label>Customer<select name="customer_id"><option value="">All customers</option><?php foreach($customers as $customer):?><option value="<?= e($customer['id']) ?>" <?= ($_GET['customer_id']??'')===$customer['id']?'selected':'' ?>><?= e($customer['name']) ?></option><?php endforeach;?></select></label><button class="secondary">Apply filters</button></form><div class="table-wrap"><table><thead><tr><th>Certificate #</th><th>Equipment</th><th>Customer</th><th>Type</th><th>Issue date</th><th>Expiry</th><th>Status</th></tr></thead><tbody><?php foreach($records as $record):$display=qhse_certificate_display_status($record);?><tr><td><a href="qhse-certificates?id=<?= e($record['id']) ?>"><strong><?= e($record['certificate_number']) ?></strong></a></td><td><?= e($record['equipment_names']?:'—') ?></td><td><?= e($record['customer_name']) ?></td><td><?= e(qhse_certificate_type_label($record['certificate_type'])) ?></td><td><?= e($record['issue_date']?:'—') ?></td><td><?= e($record['expiry_date']?:'—') ?></td><td><?= qhse_status_badge($display) ?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$records):?><div class="qhse-empty"><?= operation_icon('shield') ?><h3>No certificates match this view</h3><p>Create a certificate draft or clear the filters.</p></div><?php endif;?></section><?php endif;require __DIR__.'/includes/operations-footer.php';?>
